"""Current-review narrative and provenance; the original rubric remains in analyze.py."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
OWNED = ['folio', 'atelier', 'nocturne', 'tufte', 'zephyr-reading', 'simplex-reading', 'pulse-reading', 'litera-reading', 'darkly-reading']
BASELINES = dict(folio='folio-original', atelier='atelier-original', nocturne='nocturne-original', **{n: n.removesuffix('-reading') for n in OWNED if n.endswith('-reading')})
E = html.escape


def history_table(data):
    before = {t['id']: t for t in json.loads((ROOT / 'previous-scores.json').read_text())}
    november10 = {t['id']: t for t in json.loads((ROOT / 'before-color-repair-scores.json').read_text())}
    current = {t['id']: t for t in data}
    rows = []
    for name in OWNED:
        a, b = before[name], current[name]
        prior = november10[name]
        original = current.get(BASELINES.get(name))
        baseline = f'{original["typography"]} / {original["design"]["total"]}' if original else 'October baseline'
        rows.append(f'<tr><th scope="row"><a href="#theme-{name}">{E(b["name"])}</a></th><td>{baseline}</td><td>{a["typography"]} / {a["design"]["total"]}</td><td>{prior["typography"]} / {prior["design"]["total"]}</td><td><strong>{b["typography"]} / {b["design"]["total"]}</strong></td><td>{b["typography"]-prior["typography"]:+d} / {b["design"]["total"]-prior["design"]["total"]:+d}</td></tr>')
    return '<div class="table-wrap"><table class="rubric"><caption>Typography / design, each out of 100. October → November 10 → November 11 uses the same rubric.</caption><thead><tr><th>Owned theme</th><th>Original custom / stock</th><th>16 October</th><th>10 November</th><th>11 November</th><th>Change since 10 November</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div><p class="caption">The original custom snapshots and stock themes are unchanged. Current owned themes use the lower of both mode scores; the October Reading themes had only their native mode. Expand a theme to see each current mode. Tufte had no separate original snapshot; its October result is preserved in the archive.</p>'


def current_intro(data):
    return '''<section id="changes"><h2>Nine updated themes, the same scorecard</h2><p>The 10 November review imported the exact nine merged foundation revisions verified upstream on 9 November. The 11 November follow-up repairs component and syntax colors in Pulse Reading, Litera Reading and Darkly Reading; their typography, spacing and shape are unchanged. All nine now have explicit light/dark palettes, semantic roles, reading and presentation profiles, spacing, shape, and state pairs. The gallery exercises their reading profiles. The 25 stock Bootswatches, native Bootstrap, and three original custom snapshots remain unchanged.</p>'''+history_table(data)+'''<div class="callout"><p><strong>A lower typography score is a real rubric tradeoff.</strong> The new themes deliberately use 1.60 leading. The unchanged Butterick bands award that 12/20, compared with 20/20 at 1.20–1.45. Larger 18–20px prose, 16px code, and explicit controls can improve practical use while aligning less closely with this prescriptive scorecard. The score measures fit to the rubric; it is not a reader study.</p></div><p>Folio now uses Source Serif 4 for ordinary headings; Caslon is an optional display role. Atelier uses 18px DM Sans. Folio, Nocturne, Tufte, and Litera Reading use 20px serif prose. The other Reading themes use 18px prose. All nine use 16px code, 16px interface text, 14px metadata roles, 36px titles, and a separate optional 48px display role. Presentation sizes are published for downstream consumers and do not enlarge the document interface.</p><p><a href="history/2026-10-16/typography-report.html">Read the unchanged October typography report</a> · <a href="history/2026-10-16/visual-design-report.html">October design report</a> · <a href="theme-guide.html">Current theme handbook</a> · <a href="./?group=comparisons">Compare the actual pages</a></p></section>'''


def foundations_section():
    checks = json.loads((ROOT / 'foundations-checks.json').read_text())
    scores = {r['id']: r for r in json.loads((ROOT / 'scores.json').read_text())}
    total = sum(len(r['sourceChecks']) for r in checks)
    targets = [('pulse-reading', 'dark', 'foundation-secondary', 1.178), ('litera-reading', 'light', 'foundation-selected', 3.712), ('litera-reading', 'dark', 'foundation-selected', 3.712)]
    rows = []
    for name, mode, label, old in targets:
        context = next(r for r in checks if r['id'] == name and r['mode'] == mode)
        ratios = [c['ratio'] for b in context['browser'] for c in b['renderedText'] if c['label'] == label]
        value = min(ratios)
        rows.append(f'<tr><th>{E(name)} / {mode}</th><td>{label.removeprefix("foundation-")}</td><td>{old:.2f}:1</td><td>{value:.2f}:1</td><td><a href="previews/{name}/foundations.html?mode={mode}">Current specimen</a></td></tr>')
    light = next(m for m in scores['darkly-reading']['modes'] if m['mode'] == 'light')
    rows.append(f'<tr><th>darkly-reading / light</th><td>Sampled syntax minimum</td><td>4.34:1</td><td>{light["metrics"]["syntaxContrast"]:.2f}:1</td><td><a href="previews/darkly-reading/code.html?mode=light">Current code</a></td></tr>')
    failures = [(r['id'],r['mode'],b['viewport'],c['label']) for r in checks for b in r['browser'] for c in b['renderedText'] if not c['passes']]
    status = 'All sampled rendered foundation text clears 4.5:1 at both widths.' if not failures else f'{len(failures)} sampled foundation contexts still need repair; see raw checks.'
    return f'''<section id="foundations"><h2>Foundations and rendered controls</h2><p>The supplementary specimen exercises semantic actions, disabled buttons, associated errors, selected navigation, captions and forms. Its 36 observations supplement the fixed rubrics without adding points. <strong>{total} intended source pairs clear their stated thresholds:</strong> 5:1 ordinary roles and state text, 4.5:1 action ink, and 3:1 meaningful edges. {status}</p><section id="color-repairs"><h3>Three color repairs, 11 November 2026</h3><p>Pulse’s secondary action now uses its neutral foundation fill and ink. Litera’s selected navigation uses the explicit selected pair. Darkly’s weak light-mode syntax families now use named roles shared across SmallDocs and Quarto. Both modes and renderers are checked in the source repositories; this table reports the SmallDocs specimens used for scoring.</p><div class="table-wrap"><table class="rubric"><caption>Before / after; current component minima include both 1280px and 390px widths.</caption><thead><tr><th>Context</th><th>Role</th><th>10 November</th><th>11 November</th><th>Evidence</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div><p><strong>Prose leading remains 1.60.</strong> Type sizes, font roles, spacing and shape are unchanged. The fixed Butterick spacing deduction remains; color repairs do not buy typography points by reducing line spacing. The old component evidence and all previous scores are preserved in the <a href="history/2026-11-10/">10 November archive</a>.</p></section><p>The capture inventory retains unchanged November 10 observations for six owned themes. The three repaired themes were recaptured in both modes at both widths on 11 November. <a href="typography-audit/current-screenshots.json">Capture dates and screenshot hashes</a> distinguish these batches. Source checks do not certify every selector, interaction state, device or whole-site accessibility. Fresh scores use SmallDocs; Quarto source-consumer checks are supplementary.</p><p><a href="typography-audit/foundations-checks.json">All foundation checks</a> · <a href="typography-audit/foundations-measurements.json">Raw observations</a></p></section>'''


def source_table():
    pins = json.loads((ROOT.parents[1] / 'theme-sources.json').read_text())
    rows = ''.join(f'<tr><th>{E(p["name"])}</th><td><a href="{p["repository"]}/commit/{p["commit"]}"><code>{p["commit"][:12]}</code></a></td><td><code>{p["foundations_sha256"]}</code></td></tr>' for p in pins if p['name'] in OWNED)
    return '<h3>Exact current source identities</h3><div class="table-wrap"><table class="rubric"><thead><tr><th>Theme</th><th>Commit</th><th>Foundation SHA-256</th></tr></thead><tbody>'+rows+'</tbody></table></div>'


METHOD = '''<section id="method"><h2>What was evaluated</h2><p>The comparison still contains 38 designs. Thirteen have paired light/dark styles: nine current owned themes, three original custom snapshots, and the native Bootstrap baseline. The other 25 are unchanged stock Bootswatches. This gives 51 theme/mode combinations. Companion modes belong to the owned Reading adaptations; they are not presented as upstream Bootswatch releases.</p><p>The initial 10 November capture covered all 18 owned theme/mode combinations at 1280 × 844 and 390 × 844 CSS pixels on the identical Typography and Code specimens, plus desktop Controls: 72 prose/code and 18 control observations. Unchanged stock, Bootstrap, and original custom observations are carried forward from October after verifying their assets. The combined score dataset has 204 prose/code and 51 desktop control observations. The separate Foundations specimen adds 36 observations. On11 November, the three repaired themes were recaptured: 24 prose/code, 6 control and 12 foundation observations, plus 42 screenshots. The other six owned themes retain their verified November 10 records; unchanged stock/native/original records remain from October. Capture dates are preserved per record.</p><p>Captures use actual fixed-width iframes in the same browser. This tests CSS reflow, not physical-device behavior. Each capture awaits font loading and the declared CSS color-transition duration before sampling. Saved current images show the first 650px of each frame; full pages remain in the gallery. The committed browser harness, raw observations, screenshot inventory, source revisions, and SHA-256 manifest hashes accompany this report.</p><h3>Measurement and judgment</h3><ul><li>The two short prose paragraphs are unchanged. Character counts use rendered character-range geometry and exclude the final line of each paragraph. Roughly 490 characters estimate line capacity; a long chapter may move a borderline result.</li><li>Each mode is scored independently. The lower light/dark total becomes the theme score. The new Reading companions therefore expand the tested scope compared with October's native-only Reading modes.</li><li>All typography weights and deduction bands are unchanged. The design rubric and editorial judgment anchors are unchanged. Existing hierarchy, grouping, layout, surface, and personality awards are retained where the new specimens show no material reason to change them; measured color points are recalculated.</li><li>Contrast composites ancestor colors in sRGB. Quartz's horizontal gradient is sampled across the reading column; component gradients and Vapor's vertical gradient use conservative stop ranges. These old gradient estimates still need pixel-location verification for sign-off.</li><li>The fixed scores cover sampled normal-state text. The separate foundation checks cover intended source pairs and selected rendered roles; they do not certify every interaction state, icon, syntax class, device, or accessibility criterion.</li><li>The shared specimen does not exercise sidebars, contents panels, marginal notes, or complex Tufte columns. The pinned upstream repositories include separate SmallDocs and Quarto consumers and browser helpers; their evidence is supplementary, not a fresh Quarto score here.</li><li>This is a self-review using explicit measurements and editorial awards, not an independent reader study or endorsement. A high score means close alignment with this short rubric. Treat small differences as ties and inspect flagged components before adopting a theme.</li></ul><p class="caption">Reviewed 10 November; color follow-up 11 November 2026. The October reports, measurements, scores, and screenshots are preserved in <a href="history/2026-10-16/">the review archive</a>. The earlier source snapshot is <code>69c7339</code>; the original custom designs remain at tag <code>before-reading-redesign-2026-10-16</code>. No proprietary PDF or extracts are distributed.</p>'''+source_table()+'</section>'
